1	// 3D view (Three.js). Draws what Python computed; no orbital or DOP math happens here.
2	import * as THREE from "three";
3	import { OrbitControls } from "three/addons/controls/OrbitControls.js";
4	import { trialColor, rgb01, FADE } from "./trialcolors.js";
5	import { buildEarthGeometry } from "./earth.js";
6	import { satelliteGeometries } from "./satmodels.js";
7	
8	const R_EARTH = 6378.137;      // km; scene units are Earth radii
9	const K = 1 / R_EARTH;
10	
11	// Physical frame (x, y, z=north) -> Three.js frame (y is up): (x, y, z) -> (x, z, -y).
12	const toScene = (p) => new THREE.Vector3(p[0] * K, p[2] * K, -p[1] * K);
13	const dirToScene = (d) => new THREE.Vector3(d[0], d[2], -d[1]);     // a direction (no scaling)
14	const EARTH_CENTRE = new THREE.Vector3(0, 0, 0);
15	
16	// onPick(lat, lon): the Earth was clicked.
17	// onHover(i, x, y): satellite i (or -1 for none) is under the mouse, at (x, y) pixels inside the container.
18	// land: the land/ocean grid from earth.js (or null for a plain sphere).
19	// onSatClick(i): satellite i was clicked (to switch it off or on).
20	export function createGlobe(container, onPick, onHover, land, onSatClick) {
21	  const scene = new THREE.Scene();
22	  const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100);
23	  camera.position.set(6, 4, 9);
24	
25	  const renderer = new THREE.WebGLRenderer({ antialias: true });
26	  renderer.setPixelRatio(window.devicePixelRatio || 1);
27	  container.appendChild(renderer.domElement);
28	
29	  const controls = new OrbitControls(camera, renderer.domElement);
30	  controls.enablePan = false;
31	  controls.minDistance = 1.6;
32	  controls.maxDistance = 20;
33	
34	  scene.add(new THREE.AmbientLight(0xffffff, 0.8));
35	  const sun = new THREE.DirectionalLight(0xffffff, 1.2);
36	  sun.position.set(5, 3, 4);
37	  scene.add(sun);
38	
39	  // Everything fixed to the ground (the Earth, its graticule, Monte-Carlo dots) lives in
40	  // earthGroup, which is turned each update by the Earth's rotation angle from Python.
41	  // Satellites, orbit rings and the receiver marker are in the inertial frame (scene level).
42	  const earthGroup = new THREE.Group();
43	  scene.add(earthGroup);
44	
45	  // Low-poly Earth (land/ocean from the land grid) with a lat/lon graticule every 30 degrees
46	  // (equator and prime meridian highlighted). Without the land grid: a plain dark-blue sphere.
47	  const earth = new THREE.Mesh(
48	    land ? buildEarthGeometry(land) : new THREE.SphereGeometry(1, 64, 48),
49	    land ? new THREE.MeshPhongMaterial({ vertexColors: true, flatShading: true, shininess: 4, specular: 0x111111 })
50	         : new THREE.MeshPhongMaterial({ color: 0x1b3550, shininess: 8 }));
51	  earthGroup.add(earth);
52	  addGraticule(earthGroup);
53	
54	  // North pole marker so orientation is clear
55	  const pole = new THREE.Line(
56	    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 1.35, 0)]),
57	    new THREE.LineBasicMaterial({ color: 0xffffff }));
58	  earthGroup.add(pole);
59	
60	  // Receiver marker
61	  const receiver = new THREE.Mesh(
62	    new THREE.SphereGeometry(0.025, 16, 12), new THREE.MeshBasicMaterial({ color: 0xff3b30 }));
63	  scene.add(receiver);
64	
65	  // Line-of-sight lines to visible satellites (the buffer is sized for the constellation in setConstellation)
66	  const losGeom = new THREE.BufferGeometry();
67	  losGeom.setAttribute("position", new THREE.BufferAttribute(new Float32Array(6), 3));
68	  losGeom.setDrawRange(0, 0);
69	  const los = new THREE.LineSegments(losGeom, new THREE.LineBasicMaterial({ color: 0x7CFC9A, transparent: true, opacity: 0.6 }));
70	  los.frustumCulled = false;   // its points change every update; the initial bounding sphere would be wrong
71	  scene.add(los);
72	
73	  // Sight lines to satellites above the horizon but hidden by the terrain (red, dashed)
74	  const blockedGeom = new THREE.BufferGeometry();
75	  blockedGeom.setAttribute("position", new THREE.BufferAttribute(new Float32Array(6), 3));
76	  blockedGeom.setDrawRange(0, 0);
77	  const blockedLos = new THREE.LineSegments(blockedGeom,
78	    new THREE.LineDashedMaterial({ color: 0xff5252, dashSize: 0.08, gapSize: 0.06, transparent: true, opacity: 0.8 }));
79	  blockedLos.frustumCulled = false;
80	  scene.add(blockedLos);
81	  let blockedCount = 0;                     // how many dashed lines are drawn (for tests)
82	
83	  // ---- Monte-Carlo trial dots -------------------------------------------------------
84	  // Each trial appears as a big flash in its PDOP colour that, over FLASH_S seconds, shrinks and
85	  // darkens (colour x FADE); it is then copied into a permanent layer of small dark dots. The
86	  // permanent layer is drawn first (renderOrder 1) and flashes after it (renderOrder 2), so old
87	  // dots never cover a flash. Colours are passed to the shaders as plain sRGB numbers.
88	  const FLASH_S = 0.5, FLASH_PX = 14, DOT_PX = 4;
89	  const CAP_FLASH = 8192, CAP_DOT = 200000, DOT_R = 1.004;
90	  const px = renderer.getPixelRatio();
91	  const roundDot = `vec2 c = gl_PointCoord - 0.5; if (dot(c, c) > 0.25) discard;`;
92	
93	  const dotPos = new Float32Array(CAP_DOT * 3);
94	  const dotCol = new Float32Array(CAP_DOT * 3);
95	  const dotGeom = new THREE.BufferGeometry();
96	  dotGeom.setAttribute("position", new THREE.BufferAttribute(dotPos, 3));
97	  dotGeom.setAttribute("aColor", new THREE.BufferAttribute(dotCol, 3));
98	  dotGeom.setDrawRange(0, 0);
99	  const dots = new THREE.Points(dotGeom, new THREE.ShaderMaterial({
100	    uniforms: { uPx: { value: DOT_PX * px } },
101	    vertexShader: `uniform float uPx; attribute vec3 aColor; varying vec3 vColor;
102	      void main() { vColor = aColor; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); gl_PointSize = uPx; }`,
103	    fragmentShader: `varying vec3 vColor;
104	      void main() { ${roundDot} gl_FragColor = vec4(vColor, 1.0); }`,
105	    depthWrite: false,
106	  }));
107	  dots.renderOrder = 1;
108	  dots.frustumCulled = false;
109	  earthGroup.add(dots);                     // trial dots are ground-fixed, so they turn with the Earth
110	
111	  const flashPos = new Float32Array(CAP_FLASH * 3);
112	  const flashCol = new Float32Array(CAP_FLASH * 3);
113	  const flashBirth = new Float32Array(CAP_FLASH).fill(-1e6);   // seconds; -1e6 = empty slot
114	  const flashGeom = new THREE.BufferGeometry();
115	  flashGeom.setAttribute("position", new THREE.BufferAttribute(flashPos, 3));
116	  flashGeom.setAttribute("aColor", new THREE.BufferAttribute(flashCol, 3));
117	  flashGeom.setAttribute("birth", new THREE.BufferAttribute(flashBirth, 1));
118	  const flashMat = new THREE.ShaderMaterial({
119	    uniforms: {
120	      uTime: { value: 0 }, uFade: { value: FADE },
121	      uLife: { value: FLASH_S }, uStartPx: { value: FLASH_PX * px }, uEndPx: { value: DOT_PX * px },
122	    },
123	    vertexShader: `uniform float uTime, uLife, uStartPx, uEndPx, uFade;
124	      attribute vec3 aColor; attribute float birth; varying vec3 vColor;
125	      void main() {
126	        float a = clamp((uTime - birth) / uLife, 0.0, 1.0);        // 0 = just born, 1 = faded
127	        vColor = aColor * mix(1.0, uFade, a);                       // darkens to the colour the permanent dot keeps
128	        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
129	        gl_PointSize = mix(uStartPx, uEndPx, a);
130	        if (a >= 1.0) gl_Position = vec4(2.0, 2.0, 2.0, 1.0);        // finished: off-screen (it lives on as a dark dot)
131	      }`,
132	    fragmentShader: `varying vec3 vColor;
133	      void main() { ${roundDot} gl_FragColor = vec4(vColor, 1.0); }`,
134	    depthWrite: false,
135	  });
136	  const flashes = new THREE.Points(flashGeom, flashMat);
137	  flashes.renderOrder = 2;
138	  flashes.frustumCulled = false;
139	  earthGroup.add(flashes);
140	
141	  // The flash buffer is a ring: slots head..tail-1 are live, in birth order.
142	  let head = 0, tail = 0, dotCount = 0;
143	
144	  // lat/lon (degrees) on a sphere of radius r -> scene coordinates (same mapping as toScene)
145	  function latLonToScene(lat, lon, r) {
146	    const la = (lat * Math.PI) / 180, lo = (lon * Math.PI) / 180;
147	    return [r * Math.cos(la) * Math.cos(lo), r * Math.sin(la), -r * Math.cos(la) * Math.sin(lo)];
148	  }
149	
150	  function retireOldest() {
151	    const s = head % CAP_FLASH;
152	    if (dotCount < CAP_DOT) {
153	      dotPos.set(flashPos.subarray(3 * s, 3 * s + 3), 3 * dotCount);
154	      for (let c = 0; c < 3; c++) dotCol[3 * dotCount + c] = flashCol[3 * s + c] * FADE;
155	      dotCount++;
156	      dotGeom.setDrawRange(0, dotCount);
157	      dotGeom.attributes.position.needsUpdate = true;
158	      dotGeom.attributes.aColor.needsUpdate = true;
159	    }
160	    flashBirth[s] = -1e6;
161	    flashGeom.attributes.birth.needsUpdate = true;
162	    head++;
163	  }
164	
165	  /** Add one flash per trial. Births are spread evenly over [t0ms, t1ms] so they are staggered. */
166	  function spawnTrials(points, t0ms, t1ms, pdopThreshold) {
167	    const k = points.lat.length;
168	    for (let i = 0; i < k; i++) {
169	      if (tail - head >= CAP_FLASH) retireOldest();
170	      const s = tail % CAP_FLASH;
171	      flashPos.set(latLonToScene(points.lat[i], points.lon[i], DOT_R), 3 * s);
172	      flashCol.set(rgb01(trialColor(points.pdop[i], pdopThreshold)), 3 * s);
173	      flashBirth[s] = (t0ms + ((i + 0.5) / k) * (t1ms - t0ms)) / 1000;
174	      tail++;
175	    }
176	    flashGeom.attributes.position.needsUpdate = true;
177	    flashGeom.attributes.aColor.needsUpdate = true;
178	    flashGeom.attributes.birth.needsUpdate = true;
179	  }
180	
181	  function clearTrials() {
182	    head = tail = dotCount = 0;
183	    flashBirth.fill(-1e6);
184	    flashGeom.attributes.birth.needsUpdate = true;
185	    dotGeom.setDrawRange(0, 0);
186	  }
187	
188	  function updateTrials() {
189	    const now = performance.now() / 1000;
190	    flashMat.uniforms.uTime.value = now;
191	    while (head < tail && now - flashBirth[head % CAP_FLASH] >= FLASH_S) retireOldest();
192	  }
193	
194	  // ---- the constellation: satellites and orbit rings -----------------------------------------
195	  // setConstellation() (below) builds one sphere per satellite and one ring per distinct orbit.
196	  // Satellites that are switched off are drawn as faint ghosts; a ring is drawn faintly too if
197	  // every satellite on it is switched off.
198	  let normals = [];      // orbit normal of each satellite (scene axes): the axis of its solar wings
199	  let sats = [];         // one mesh per satellite
200	  let ringLines = [];    // one line per distinct orbit
201	  let ringOf = [];       // which ring each satellite is on
202	  let ringActive = [];   // whether a ring has any switched-on satellite
203	  let enabled = [];      // whether each satellite is switched on (from the last update)
204	  let visible = [];      // whether each satellite is above the mask and switched on (from the last update)
205	
206	  // ---- satellite hover ----------------------------------------------------------------
207	  // The satellite under the mouse is found in screen space: the nearest satellite within
208	  // HOVER_PX pixels of the pointer that is not hidden behind the Earth. Its orbit ring is
209	  // highlighted (the other rings dim) and the page is told so it can show a tooltip.
210	  const HOVER_PX = 14;
211	  const earthSphere = new THREE.Sphere(new THREE.Vector3(), 1);
212	  let pointer = null;                       // mouse position in container pixels, or null
213	  let hovered = -1, lastReported = null;
214	  let clickCandidate = -1;                  // the satellite that was under the mouse when it was pressed
215	
216	  const MODEL_SIZE = 1.6;   // the low-poly models are drawn this much larger than their built size, to be seen on the globe
217	  function satScale(i) { return MODEL_SIZE * (i === hovered ? 2.2 : !enabled[i] ? 0.7 : visible[i] ? 1.3 : 0.8); }
218	  function satOpacity(i) { return !enabled[i] ? 0.12 : visible[i] ? 1 : 0.35; }
219	  function ringOpacity(r) { return hovered >= 0 ? (r === ringOf[hovered] ? 1.0 : 0.1) : ringActive[r] ? 0.35 : 0.06; }
220	
221	  function applyHighlight() {
222	    ringLines.forEach((line, r) => { line.material.opacity = ringOpacity(r); });
223	    sats.forEach((m, i) => m.scale.setScalar(satScale(i)));
224	  }
225	
226	  function pickSatellite() {
227	    let best = -1, bestDist = HOVER_PX;
228	    if (pointer && sats.length) {
229	      const w = container.clientWidth, h = container.clientHeight;
230	      camera.updateMatrixWorld();
231	      sats.forEach((m, i) => {
232	        const ndc = m.position.clone().project(camera);
233	        if (ndc.z > 1) return;                                           // behind the camera
234	        const d = Math.hypot((ndc.x * 0.5 + 0.5) * w - pointer.x, (-ndc.y * 0.5 + 0.5) * h - pointer.y);
235	        if (d >= bestDist) return;
236	        const toSat = m.position.clone().sub(camera.position);
237	        const dist = toSat.length();
238	        const hit = new THREE.Ray(camera.position.clone(), toSat.normalize()).intersectSphere(earthSphere, new THREE.Vector3());
239	        if (hit && camera.position.distanceTo(hit) < dist) return;       // the Earth is in front of it
240	        best = i; bestDist = d;
241	      });
242	    }
243	    if (best !== hovered) { hovered = best; applyHighlight(); }
244	    const report = hovered < 0 ? "none" : `${hovered}:${Math.round(pointer.x)}:${Math.round(pointer.y)}`;
245	    if (report !== lastReported) { lastReported = report; onHover(hovered, pointer ? pointer.x : 0, pointer ? pointer.y : 0); }
246	  }
247	
248	  /**
249	   * Replace the satellites and rings.
250	   *   colors: CSS colour of each satellite; ringOf: ring index of each satellite;
251	   *   paths: points of each ring (inertial km); ringColors, ringActive: colour / "has a satellite switched on" per ring.
252	   */
253	  function setConstellation(c) {
254	    sats.forEach((m) => { scene.remove(m); m.material.dispose(); });
255	    ringLines.forEach((l) => { scene.remove(l); l.geometry.dispose(); l.material.dispose(); });
256	    const models = satelliteGeometries();
257	    sats = c.colors.map((color, i) => {
258	      const material = new THREE.MeshLambertMaterial({ color, vertexColors: true, transparent: true, side: THREE.DoubleSide });
259	      const m = new THREE.Mesh(models[c.models[i]] || models.generic, material);
260	      scene.add(m);
261	      return m;
262	    });
263	    ringLines = c.paths.map((pts, r) => {
264	      const line = new THREE.LineLoop(
265	        new THREE.BufferGeometry().setFromPoints(pts.map(toScene)),
266	        new THREE.LineBasicMaterial({ color: c.ringColors[r], transparent: true, opacity: 0.35 }));
267	      scene.add(line);
268	      return line;
269	    });
270	    ringOf = c.ringOf;
271	    normals = c.normals.map(dirToScene);
272	    ringActive = c.ringActive;
273	    enabled = c.colors.map(() => true);
274	    visible = c.colors.map(() => false);
275	    losGeom.setAttribute("position", new THREE.BufferAttribute(new Float32Array(Math.max(1, c.colors.length) * 6), 3));
276	    losGeom.setDrawRange(0, 0);
277	    blockedGeom.setAttribute("position", new THREE.BufferAttribute(new Float32Array(Math.max(1, c.colors.length) * 6), 3));
278	    blockedGeom.setDrawRange(0, 0);
279	    hovered = -1; lastReported = null; clickCandidate = -1;
280	    applyHighlight();
281	  }
282	
283	  function update(snap) {
284	    if (snap.sat_positions.length !== sats.length) return;     // the constellation just changed; the next snapshot will match
285	    enabled = snap.enabled;
286	    visible = snap.visible;
287	    // Rotation about physical +z equals rotation about scene +y (the mapping toScene is a proper rotation)
288	    earthGroup.rotation.y = (snap.earth_angle_deg * Math.PI) / 180;
289	    const rx = toScene(snap.receiver);
290	    receiver.position.copy(rx);
291	
292	    const buf = losGeom.attributes.position.array, bbuf = blockedGeom.attributes.position.array;
293	    let k = 0, kb = 0;
294	    snap.sat_positions.forEach((p, i) => {
295	      const pos = toScene(p);
296	      sats[i].position.copy(pos);
297	      sats[i].up.copy(normals[i]);                // wings along the orbit normal ...
298	      sats[i].lookAt(EARTH_CENTRE);               // ... and the body's +z (antennas) facing the Earth
299	      sats[i].material.opacity = satOpacity(i);
300	      sats[i].scale.setScalar(satScale(i));
301	      if (visible[i]) {
302	        buf.set([rx.x, rx.y, rx.z, pos.x, pos.y, pos.z], k);
303	        k += 6;
304	      } else if (snap.blocked[i]) {                              // above the horizon, hidden by the valley walls
305	        bbuf.set([rx.x, rx.y, rx.z, pos.x, pos.y, pos.z], kb);
306	        kb += 6;
307	      }
308	    });
309	    losGeom.attributes.position.needsUpdate = true;
310	    losGeom.setDrawRange(0, k / 3);
311	    blockedGeom.attributes.position.needsUpdate = true;
312	    blockedGeom.setDrawRange(0, kb / 3);
313	    blockedLos.computeLineDistances();                             // dashes need the distance along each line
314	    blockedCount = kb / 6;
315	  }
316	
317	  // Click (not drag) on the Earth -> report latitude/longitude
318	  const ray = new THREE.Raycaster();
319	  let down = null;
320	  renderer.domElement.addEventListener("pointerdown", (e) => {
321	    down = [e.clientX, e.clientY];
322	    clickCandidate = hovered;                                   // remember it: pressing hides the tooltip and clears `hovered`
323	    pointer = null;
324	  });
325	  renderer.domElement.addEventListener("pointermove", (e) => {
326	    if (e.buttons) return;                                      // dragging to rotate: no tooltip
327	    const r = renderer.domElement.getBoundingClientRect();
328	    pointer = { x: e.clientX - r.left, y: e.clientY - r.top };
329	  });
330	  renderer.domElement.addEventListener("pointerleave", () => { pointer = null; });
331	  renderer.domElement.addEventListener("pointerup", (e) => {
332	    if (!down || Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 4) return;
333	    if (clickCandidate >= 0) {                                  // a click on a satellite switches it off or on
334	      const i = clickCandidate;
335	      clickCandidate = -1;
336	      onSatClick(i);
337	      return;
338	    }
339	    const r = renderer.domElement.getBoundingClientRect();
340	    ray.setFromCamera(new THREE.Vector2(((e.clientX - r.left) / r.width) * 2 - 1,
341	                                        -((e.clientY - r.top) / r.height) * 2 + 1), camera);
342	    const hit = ray.intersectObject(earth)[0];
343	    if (!hit) return;
344	    // Undo the Earth's current rotation to get Earth-fixed coordinates, then invert toScene:
345	    // scene (x, y, z) -> physical (x, -z, y)
346	    const p = earthGroup.worldToLocal(hit.point.clone());
347	    const x = p.x, y = -p.z, z = p.y;
348	    onPick(Math.asin(z / p.length()) * 180 / Math.PI, Math.atan2(y, x) * 180 / Math.PI);
349	  });
350	
351	  function resize() {
352	    const w = container.clientWidth, h = container.clientHeight;
353	    renderer.setSize(w, h);
354	    camera.aspect = w / h;
355	    camera.updateProjectionMatrix();
356	  }
357	  new ResizeObserver(resize).observe(container);
358	  resize();
359	
360	  renderer.setAnimationLoop(() => {
361	    updateTrials();
362	    controls.update();
363	    pickSatellite();           // every frame: satellites and the camera move even when the mouse does not
364	    renderer.render(scene, camera);
365	  });
366	
367	  // ---- orbit preview (the Add dialog): dashed rings and see-through satellites that are not added yet ----
368	  let previewObjects = [];
369	  function clearPreview() {
370	    previewObjects.forEach((o) => {
371	      scene.remove(o);
372	      if (o.isLine) o.geometry.dispose();            // the satellite geometries are shared: keep them
373	      o.material.dispose();
374	    });
375	    previewObjects = [];
376	  }
377	  /** pv = {paths, positions, normals, color, models} (inertial km, as from api.preview). */
378	  function setPreview(pv) {
379	    clearPreview();
380	    const models = satelliteGeometries();
381	    pv.paths.forEach((pts) => {
382	      const line = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts.map(toScene)),
383	        new THREE.LineDashedMaterial({ color: pv.color, dashSize: 0.12, gapSize: 0.08, transparent: true, opacity: 0.9 }));
384	      line.computeLineDistances();
385	      scene.add(line);
386	      previewObjects.push(line);
387	    });
388	    pv.positions.forEach((p, i) => {
389	      const m = new THREE.Mesh(models[pv.models[i]] || models.generic,
390	        new THREE.MeshLambertMaterial({ color: pv.color, vertexColors: true, transparent: true, opacity: 0.55, side: THREE.DoubleSide }));
391	      m.position.copy(toScene(p));
392	      m.up.copy(dirToScene(pv.normals[i]));
393	      m.lookAt(EARTH_CENTRE);
394	      m.scale.setScalar(MODEL_SIZE * 1.3);
395	      scene.add(m);
396	      previewObjects.push(m);
397	    });
398	  }
399	
400	  // ---- a map on the ground (the Compare tab's PDOP map) -------------------------------------------------------
401	  // One square cell per grid point (cellDeg wide, centred on the point), coloured per cell, fixed to the
402	  // Earth so it turns with it. Drawn just above the surface, semi-transparent so the continents show.
403	  let groundMap = null;
404	  function clearGroundMap() {
405	    if (!groundMap) return;
406	    earthGroup.remove(groundMap);
407	    groundMap.geometry.dispose();
408	    groundMap.material.dispose();
409	    groundMap = null;
410	  }
411	  function setGroundMap({ lats, lons, colors, cellDeg }) {
412	    clearGroundMap();
413	    const r = 1.006, h = cellDeg / 2, pos = [], col = [];
414	    const corner = (la, lo) => {
415	      const a = (la * Math.PI) / 180, b = (lo * Math.PI) / 180;
416	      return [r * Math.cos(a) * Math.cos(b), r * Math.sin(a), -r * Math.cos(a) * Math.sin(b)];     // same mapping as toScene
417	    };
418	    const c = new THREE.Color();
419	    lats.forEach((la, k) => {
420	      const lo = lons[k];
421	      const p1 = corner(la - h, lo - h), p2 = corner(la - h, lo + h), p3 = corner(la + h, lo + h), p4 = corner(la + h, lo - h);
422	      pos.push(...p1, ...p2, ...p3, ...p1, ...p3, ...p4);
423	      c.set(colors[k]);
424	      for (let v = 0; v < 6; v++) col.push(c.r, c.g, c.b);
425	    });
426	    const geom = new THREE.BufferGeometry();
427	    geom.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
428	    geom.setAttribute("color", new THREE.Float32BufferAttribute(col, 3));
429	    groundMap = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.6,
430	                                                                   depthWrite: false, side: THREE.DoubleSide }));
431	    groundMap.renderOrder = 0.5;
432	    earthGroup.add(groundMap);
433	  }
434	
435	  /** Where satellite i is on screen, in pixels inside the container (for tests and debugging). */
436	  function screenOf(i) {
437	    camera.updateMatrixWorld();
438	    const ndc = sats[i].position.clone().project(camera);
439	    return { x: (ndc.x * 0.5 + 0.5) * container.clientWidth, y: (-ndc.y * 0.5 + 0.5) * container.clientHeight };
440	  }
441	
442	  return { update, setConstellation, spawnTrials, clearTrials, screenOf, blockedLines: () => blockedCount,
443	           setPreview, clearPreview, previewCount: () => previewObjects.length,
444	           setGroundMap, clearGroundMap, groundMapCells: () => (groundMap ? groundMap.geometry.attributes.position.count / 6 : 0),
445	           satColor: (i) => `#${sats[i].material.color.getHexString()}`,
446	           // for tests: the model's +z (antenna) and +y (wing) axes, and its position, in scene axes
447	           satAxes: (i) => { const e = sats[i].matrixWorld.elements; return { y: [e[4], e[5], e[6]], z: [e[8], e[9], e[10]], p: sats[i].position.toArray() }; } };
448	}
449	
450	function addGraticule(scene) {
451	  const r = 1.002, N = 120;
452	  const material = (c) => new THREE.LineBasicMaterial({ color: c });
453	  for (let lat = -60; lat <= 60; lat += 30) {
454	    const pts = [];
455	    for (let i = 0; i <= N; i++) {
456	      const lon = (2 * Math.PI * i) / N, la = (lat * Math.PI) / 180;
457	      pts.push(toScene([r * R_EARTH * Math.cos(la) * Math.cos(lon), r * R_EARTH * Math.cos(la) * Math.sin(lon), r * R_EARTH * Math.sin(la)]));
458	    }
459	    scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), material(lat === 0 ? 0xf2c14e : 0x3b5878)));
460	  }
461	  for (let lon = 0; lon < 360; lon += 30) {
462	    const pts = [];
463	    for (let i = 0; i <= N; i++) {
464	      const la = (2 * Math.PI * i) / N, lo = (lon * Math.PI) / 180;
465	      pts.push(toScene([r * R_EARTH * Math.cos(la) * Math.cos(lo), r * R_EARTH * Math.cos(la) * Math.sin(lo), r * R_EARTH * Math.sin(la)]));
