1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<link rel="icon" href="data:,">
7	<title>GPS DOP Simulator</title>
8	<style>
9	  :root {
10	    --bg: #0f1419; --panel: #171d25; --line: #2a3441; --text: #dfe6ee; --muted: #8b98a8;
11	    --accent: #4fc3f7;
12	  }
13	  * { box-sizing: border-box; }
14	  body { margin: 0; background: var(--bg); color: var(--text);
15	         font: 14px/1.4 system-ui, sans-serif; }
16	  main { display: grid; grid-template-columns: 1fr 340px; height: 100vh; }
17	  #globe { position: relative; min-height: 0; }
18	  #globe canvas { display: block; }
19	  aside { background: var(--panel); border-left: 1px solid var(--line); padding: 14px 16px;
20	          overflow-y: auto; }
21	  h1 { font-size: 17px; margin: 0 0 2px; }
22	  h2 { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--muted);
23	       margin: 16px 0 6px; }
24	  .sub { color: var(--muted); font-size: 12px; margin-bottom: 8px; }
25	  .row { display: flex; gap: 8px; align-items: center; margin: 6px 0; }
26	  .row label { width: 64px; color: var(--muted); }
27	  input[type=number], select { background: var(--bg); color: var(--text); border: 1px solid var(--line);
28	         border-radius: 4px; padding: 4px 6px; width: 100%; }
29	  input[type=range] { width: 100%; }
30	  button { background: var(--accent); color: #06222e; border: 0; border-radius: 4px;
31	           padding: 5px 14px; font-weight: 600; cursor: pointer; }
32	  #status { color: var(--muted); font-size: 12px; margin-top: 4px; }
33	  #readout { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
34	  .stat { background: var(--bg); border: 1px solid var(--line); border-radius: 6px;
35	          padding: 6px 8px; }
36	  .stat b { display: block; font-size: 18px; font-variant-numeric: tabular-nums; }
37	  .stat span { color: var(--muted); font-size: 11px; }
38	  canvas#sky { width: 100%; aspect-ratio: 1; display: block; }
39	  table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
40	  td, th { text-align: right; padding: 2px 4px; border-bottom: 1px solid var(--line); font-size: 12px; }
41	  th { color: var(--muted); font-weight: 500; }
42	  td:first-child, th:first-child { text-align: left; }
43	  .dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 6px; }
44	  #sat-tip { position: absolute; z-index: 5; pointer-events: none; background: rgba(23, 29, 37, .96);
45	             border: 1px solid var(--line); border-radius: 6px; padding: 8px 10px; font-size: 12px;
46	             max-width: 280px; box-shadow: 0 2px 10px rgba(0, 0, 0, .4); }
47	  #sat-tip .name { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
48	  #sat-tip table td { border: 0; padding: 1px 0; text-align: left; vertical-align: top; }
49	  #sat-tip table td:first-child { color: var(--muted); padding-right: 10px; white-space: nowrap; }
50	  button.secondary { background: var(--bg); color: var(--text); border: 1px solid var(--line); font-weight: 500; padding: 3px 10px; }
