1	// Very low-poly satellite models (about 16-45 triangles each), drawn far larger than life so they can be
2	// seen. Each model is one merged geometry; its vertex colours are grey levels that the material colour
3	// (the constellation's colour) is multiplied by, so the solar wings come out as a darker shade.
4	//
5	// Model axes: +z points at the Earth (the body is turned with lookAt(Earth's centre)); the solar wings lie
6	// along +-y, which is set to the orbit normal, as on real navigation satellites whose wings turn about an
7	// axis roughly perpendicular to the orbit plane.
8	import * as THREE from "three";
9	import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
10	
11	const BODY = 1.0, ANTENNA = 0.85, BOOM = 0.7, WING = 0.5;      // brightness of each part
12	
13	function part(geometry, shade, x = 0, y = 0, z = 0, rotateX = 0) {
14	  const g = geometry.toNonIndexed();
15	  if (rotateX) g.rotateX(rotateX);
16	  g.translate(x, y, z);
17	  const n = g.attributes.position.count;
18	  g.setAttribute("color", new THREE.BufferAttribute(new Float32Array(n * 3).fill(shade), 3));
19	  g.deleteAttribute("uv");
20	  return g;
21	}
22	const box = (w, h, d, shade, x, y, z) => part(new THREE.BoxGeometry(w, h, d), shade, x, y, z);
23	// a flat panel in the y-x plane (a solar wing), two triangles, seen from both sides
24	const panel = (w, h, shade, x, y, z) => part(new THREE.PlaneGeometry(w, h), shade, x, y, z, Math.PI / 2);
25	const wingPair = (len, width, gap, shade, panels = 1) => {
26	  const out = [];
27	  for (const side of [-1, 1]) {
28	    for (let k = 0; k < panels; k++) {
29	      const segment = len / panels;
30	      const y = side * (gap + segment * (k + 0.5) + k * 0.004);
31	      out.push(part(new THREE.PlaneGeometry(width, segment), shade, 0, y, 0));
32	    }
33	    out.push(box(0.004, gap, 0.004, BOOM, 0, side * gap / 2, 0));   // boom from the body to the wing
34	  }
35	  return out;
36	};
37	
38	function build(parts) {
39	  const g = mergeGeometries(parts);
40	  g.computeVertexNormals();
41	  return g;
42	}
