44	// GPS III: a cube-like bus, a wide antenna panel on the Earth face, two square solar wings
45	const gps = () => build([
46	  box(0.05, 0.05, 0.055, BODY),
47	  box(0.06, 0.06, 0.008, ANTENNA, 0, 0, 0.032),
48	  ...wingPair(0.07, 0.05, 0.035, WING),
49	]);
50	
51	// Galileo: a slim bus, a small laser retro-reflector on the Earth face, two long wings of two panels each
52	const galileo = () => build([
53	  box(0.035, 0.03, 0.06, BODY),
54	  box(0.016, 0.016, 0.008, ANTENNA, 0, 0.008, 0.034),
55	  ...wingPair(0.11, 0.032, 0.025, WING, 2),
56	]);
57	
58	// BeiDou-3: a box bus, a dish antenna on the Earth face, two wings of two panels
59	const beidou = () => {
60	  const dish = new THREE.ConeGeometry(0.024, 0.014, 8, 1, true);   // open cone = a shallow dish
61	  return build([
62	    box(0.045, 0.045, 0.045, BODY),
63	    part(dish, ANTENNA, 0, 0, 0.03, -Math.PI / 2),
64	    ...wingPair(0.08, 0.04, 0.03, WING, 2),
65	  ]);
66	};
67	
68	// Satellites you add: a small cube with two short wings
69	const generic = () => build([box(0.035, 0.035, 0.035, BODY), ...wingPair(0.045, 0.028, 0.026, WING)]);
70	
71	let cache = null;
72	/** The four shared geometries: { gps, galileo, beidou, generic }. */
73	export function satelliteGeometries() {
74	  if (!cache) cache = { gps: gps(), galileo: galileo(), beidou: beidou(), generic: generic() };
75	  return cache;
76	}
77	
78	export const triangleCount = (g) => g.attributes.position.count / 3;
